const EPIC_API='https://epic.gsfc.nasa.gov/api/natural'
const EPIC_ARCHIVE='https://epic.gsfc.nasa.gov/archive/natural/'
const NASA_FALLBACK={
 image:'epic_1b_20261029214459',date:'2026-10-29 21:44:59',
 url:'/scenes/epic-20261029.jpg'
}
